  "code": "def generated_loss(batch, model_output, extra):\n    # Required inputs\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n\n    hp = extra.get('hyperparams', {})\n    alpha = extra.get('alpha', hp.get('alpha', 1.0))\n    scale = hp.get('scale', 1.9122133274536794)\n    margin = hp.get('margin', 0.05)\n    cmin = hp.get('clamp_min', -20.0)\n    cmax = hp.get('clamp_max', 20.0)\n\n    # Optional weight (defaults to 1.0)\n    weight = batch.get('weight', None)\n    if weight is None:\n        weight = 1.0\n\n    d = (lpw - lpl) - margin\n    x = alpha * scale * d\n    x = ops.clamp(x, cmin, cmax)\n    loss = -ops.logsigmoid(x)\n    loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Logistic margin ranking loss on the log-probability difference: minimizes -log(sigmoid(alpha*scale*((lpw-lpl)-margin))) to encourage lpw-lpl to exceed a positive margin, with clamping to avoid numerical issues in extreme logits."
}

