  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = extra.get('alpha', hp.get('alpha', 1.0))\n    scale = hp.get('scale', 1.9122133274536794)\n    margin = hp.get('margin', 0.05)\n    cmin = hp.get('clamp_min', -20.0)\n    cmax = hp.get('clamp_max', 20.0)\n\n    d = (lpw - lpl) - margin\n    x = ops.clamp(alpha * scale * d, cmin, cmax)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Logistic pairwise preference (Bradley-Terry / DPO-style) with a smooth margin: minimizes -log(sigmoid(alpha*scale*((lpw-lpl)-margin))). Clamping the logit maintains numerical stability without changing the monotonic preference ordering."
