{
  "name": "loss_logsigmoid_002_cost_margin",
  "intuition": "The parent loss subtracts a cost gap term linearly from the logit, which can over-penalize large gaps and destabilize gradients. I replace it with a softplus-shaped margin: require lpw-lpl to exceed a (scaled) positive cost gap before saturating logsigmoid gives low loss. This keeps the pairwise preference structure but makes the cost influence smoother and one-sided (only when cost_b>cost_a), improving stability and potentially validation objective.",
  "pseudocode": "gap_pos = relu(cost_b - cost_a); margin = beta * softplus(gap_pos / tau); x = alpha*scale*(lpw-lpl) - margin; loss = -logsigmoid(clamp(x, -20, 20))",
  "hyperparams": {
    "scale": 1.5650199779066472,
    "beta": 0.1,
    "tau": 1.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "relu",
    "softplus"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    hp = extra.get('hyperparams', {})\n    scale = float(hp.get('scale', 1.5650199779066472))\n    beta = float(hp.get('beta', 0.1))\n    tau = float(hp.get('tau', 1.0))\n\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n\n    # One-sided, smooth margin from cost gap; detached to avoid coupling gradients to cost features.\n    gap_pos = ops.relu((cost_b - cost_a).detach())\n    margin = beta * ops.softplus(gap_pos / tau)\n\n    x = alpha * scale * (lpw - lpl) - margin\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) objective with an additive cost-dependent margin; softplus provides a smooth hinge-like margin encouraging stronger log-prob separation when the cost gap favors the loser.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l",
        "cost_a",
        "cost_b"
      ],
      "optional": [
        "weight"
      ],
      "extra": [
        "hyperparams.scale",
