{
  "name": "loss_logsigmoid_002_cost_margin_m3_key_stable",
  "intuition": "The failure is a static gate expects mismatch: some pipelines provide log-probs under different keys (e.g., chosen/rejected) so directly indexing 'log_prob_w'/'log_prob_l' can be flagged as missing. To stabilize, this version (1) aliases multiple common key names to obtain winner/loser log-probs without loops, (2) keeps the objective numerically stable via a clamp on the logit before logsigmoid, and (3) applies a simple, one-sided softplus margin from the positive cost gap with a small scale and safe division to avoid extreme margins. This preserves pairwise preference semantics while preventing invalid-key failures and large-logit instability.",
  "pseudocode": "lpw = first_present(batch, ['log_prob_w','logprob_w','logp_w','log_prob_chosen','log_prob_c','logprob_chosen','chosen_log_prob'])
lpl = first_present(batch, ['log_prob_l','logprob_l','logp_l','log_prob_rejected','log_prob_r','logprob_rejected','rejected_log_prob'])
weight = batch.get('weight', None)

gap = relu((cost_b - cost_a).detach())
margin = beta * softplus(gap / max(tau, eps))

x = alpha*scale*(lpw - lpl) - margin
x = clamp(x, -20, 20)
loss = -logsigmoid(x)
if weight: loss *= weight
return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "beta": 0.05,
    "tau": 1.0,
    "eps": 1e-08
  },
  "operators_used": [
    "relu",
    "softplus",
    "clamp",
    "logsigmoid"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Accept multiple common key aliases for winner/loser log-probs to avoid expects/key mismatches.
    if 'log_prob_w' in batch:
        lpw = batch['log_prob_w']
    elif 'logprob_w' in batch:
        lpw = batch['logprob_w']
    elif 'logp_w' in batch:
        lpw = batch['logp_w']
    elif 'log_prob_chosen' in batch:
        lpw = batch['log_prob_chosen']
    elif 'log_prob_c' in batch:
        lpw = batch['log_prob_c']
    elif 'logprob_chosen' in batch:
        lpw = batch['logprob_chosen']
    else:
        lpw = batch['chosen_log_prob']

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'logprob_l' in batch:
        lpl = batch['logprob_l']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    elif 'log_prob_rejected' in batch:
        lpl = batch['log_prob_rejected']
    elif 'log_prob_r' in batch:
        lpl = batch['log_prob_r']
    elif 'logprob_rejected' in batch:
        lpl = batch['logprob_rejected']
    else:
        lpl = batch['rejected_log_prob']

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))
    scale = float(hp.get('scale', 1.0))
    beta = float(hp.get('beta', 0.05))
    tau = float(hp.get('tau', 1.0))
    eps = float(hp.get('eps', 1e-8))

    # Cost margin: one-sided, smoothed; detach to avoid gradients through cost features.
    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if (cost_a is not None) and (cost_b is not None):
        gap_pos = ops.relu((cost_b - cost_a).detach())
        denom = ops.clamp(tau, eps, 1e9)
        margin = beta * ops.softplus(gap_pos / denom)
    else:
        margin = 0.0

    x = alpha * scale * (lpw - lpl) - margin
    x = ops.clamp(x, -20.0, 20.0)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        loss = loss * weight

    return loss.mean()",
  "theoretical_basis": "Pairwise Bradley-Terry / logistic preference loss with a cost-dependent additive margin; softplus provides a smooth nonnegative margin that only activates when cost_b > cost_a, while clamping the logit keeps logsigmoid numerically stable."
}

